import './styles.css';
import { useState } from 'react';

interface Value {
  id: string;
  title: string;
  icon: string;
  color: string;
  description: string;
  questions: string[];
  examples: string[];
}

interface Reflection {
  rating: number;
  notes: string;
}

const values: Value[] = [
  {
    id: 'socially-just',
    title: 'Socially Just',
    icon: '⚖️',
    color: '#6366f1',
    description: 'AI should reduce inequalities, not deepen them. Benefits should reach marginalized communities, and harm to vulnerable groups should be actively prevented.',
    questions: [
      'Who benefits from this AI, and who might be excluded?',
      'Does this AI challenge or reinforce existing power imbalances?',
      'Are marginalized voices included in the design process?',
      'What safeguards protect vulnerable groups from harm?',
    ],
    examples: [
      'AI health tools that work in under-resourced clinics, not just wealthy hospitals',
      'Credit systems that don\'t perpetuate historical discrimination',
      'Language models that serve minority languages, not just dominant ones',
    ],
  },
  {
    id: 'community-centered',
    title: 'Community-Centered',
    icon: '👥',
    color: '#f59e0b',
    description: 'AI should serve communities, not extract from them. Communities should be involved in design, data should benefit those it comes from, and solutions should be accountable to those they affect.',
    questions: [
      'Were affected communities involved in designing this AI?',
      'Do communities have ongoing voice in how the AI is used?',
      'Who controls the data, and who benefits from it?',
      'Is the AI accountable to the people it affects?',
    ],
    examples: [
      'Farmers co-designing agricultural AI with their traditional knowledge',
      'Community data trusts where locals control how data is used',
      'Feedback mechanisms that actually change how AI operates',
    ],
  },
  {
    id: 'transformative',
    title: 'Transformative',
    icon: '🔄',
    color: '#10b981',
    description: 'AI should help change unjust systems, not just make them more efficient. The goal is better systems, not just faster ones. Technology should expand human capabilities and freedoms.',
    questions: [
      'Does this AI challenge unjust conditions, or just automate them?',
      'What kind of future does this AI build toward?',
      'Does it expand human agency, or constrain it?',
      'Could this AI be used to resist oppression, not just optimize existing systems?',
    ],
    examples: [
      'AI that helps identify and challenge discriminatory patterns, not just follow them',
      'Tools that give communities power over their own data and narratives',
      'Systems designed to eventually make themselves unnecessary',
    ],
  },
  {
    id: 'local-knowledge',
    title: 'Rooted in Local Knowledge',
    icon: '🌍',
    color: '#ec4899',
    description: 'AI should build on—not erase—existing knowledge systems. Indigenous and local knowledge has value. Multiple ways of knowing should be respected and incorporated.',
    questions: [
      'Does this AI respect and incorporate local knowledge systems?',
      'Are local languages and cultural contexts supported?',
      'Does the AI work with or against existing community practices?',
      'Who defines what counts as "valid" knowledge?',
    ],
    examples: [
      'Agricultural AI that incorporates indigenous farming practices',
      'Health systems that work alongside traditional medicine, not against it',
      'Language models trained on and by local language communities',
    ],
  },
];

function ValueCard({
  value,
  reflection,
  onReflect,
  isExpanded,
  onToggle,
}: {
  value: Value;
  reflection: Reflection;
  onReflect: (rating: number, notes: string) => void;
  isExpanded: boolean;
  onToggle: () => void;
}) {
  return (
    <div className={`value-card ${isExpanded ? 'expanded' : ''}`}>
      <div 
        className="value-header"
        style={{ borderLeftColor: value.color }}
        onClick={onToggle}
      >
        <div className="value-title">
          <span className="value-icon">{value.icon}</span>
          <span>{value.title}</span>
        </div>
        <div className="header-right">
          {reflection.rating > 0 && (
            <div className="rating-display">
              {[1, 2, 3, 4, 5].map((n) => (
                <span key={n} className={n <= reflection.rating ? 'filled' : ''}>
                  ●
                </span>
              ))}
            </div>
          )}
          <span className="expand-icon">{isExpanded ? '−' : '+'}</span>
        </div>
      </div>

      {isExpanded && (
        <div className="value-content">
          <p className="value-description">{value.description}</p>

          <div className="reflection-questions">
            <h4>Questions to Consider</h4>
            <ul>
              {value.questions.map((q, i) => (
                <li key={i}>{q}</li>
              ))}
            </ul>
          </div>

          <div className="examples-section">
            <h4>Examples in Practice</h4>
            <ul>
              {value.examples.map((ex, i) => (
                <li key={i}>{ex}</li>
              ))}
            </ul>
          </div>

          <div className="reflection-input">
            <h4>Your Reflection</h4>
            <p className="reflection-prompt">
              How well does your current or planned AI work align with this value?
            </p>

            <div className="rating-input">
              <span className="rating-label">Not at all</span>
              <div className="rating-buttons">
                {[1, 2, 3, 4, 5].map((n) => (
                  <button
                    key={n}
                    className={`rating-btn ${reflection.rating === n ? 'selected' : ''}`}
                    onClick={() => onReflect(n, reflection.notes)}
                    style={{
                      backgroundColor: reflection.rating === n ? value.color : undefined,
                    }}
                  >
                    {n}
                  </button>
                ))}
              </div>
              <span className="rating-label">Fully aligned</span>
            </div>

            <textarea
              className="notes-input"
              placeholder="Reflect on what's working, what could improve, and specific actions you could take..."
              value={reflection.notes}
              onChange={(e) => onReflect(reflection.rating, e.target.value)}
            />
          </div>
        </div>
      )}
    </div>
  );
}

function Summary({ reflections }: { reflections: Record<string, Reflection> }) {
  const completed = values.filter((v) => reflections[v.id]?.rating > 0).length;
  const avgRating = completed > 0
    ? values.reduce((sum, v) => sum + (reflections[v.id]?.rating || 0), 0) / completed
    : 0;

  const getStrengths = () => {
    return values
      .filter((v) => (reflections[v.id]?.rating || 0) >= 4)
      .map((v) => v.title);
  };

  const getGrowthAreas = () => {
    return values
      .filter((v) => (reflections[v.id]?.rating || 0) > 0 && (reflections[v.id]?.rating || 0) <= 2)
      .map((v) => v.title);
  };

  const strengths = getStrengths();
  const growthAreas = getGrowthAreas();

  return (
    <div className="summary-panel">
      <h2>Reflection Summary</h2>

      <div className="progress-section">
        <div className="progress-bar">
          <div
            className="progress-fill"
            style={{ width: `${(completed / values.length) * 100}%` }}
          />
        </div>
        <span className="progress-text">{completed}/{values.length} values reflected on</span>
      </div>

      {completed > 0 && (
        <>
          <div className="avg-rating">
            <span className="avg-label">Average alignment:</span>
            <span className="avg-value">{avgRating.toFixed(1)}/5</span>
          </div>

          {strengths.length > 0 && (
            <div className="strengths-section">
              <h4>💪 Strengths</h4>
              <div className="tag-list">
                {strengths.map((s) => (
                  <span key={s} className="tag strength">{s}</span>
                ))}
              </div>
            </div>
          )}

          {growthAreas.length > 0 && (
            <div className="growth-section">
              <h4>🌱 Growth Areas</h4>
              <div className="tag-list">
                {growthAreas.map((g) => (
                  <span key={g} className="tag growth">{g}</span>
                ))}
              </div>
            </div>
          )}
        </>
      )}

      <div className="insight-box">
        <h4>Using This Tool</h4>
        <p>
          These values come from research on what AI could look like when designed by and for African communities—but they apply broadly to any context seeking more just, equitable AI.
        </p>
        <p>
          Use your reflections to guide conversations with your team, inform procurement decisions, or shape your own AI development.
        </p>
      </div>
    </div>
  );
}

export default function App() {
  const [reflections, setReflections] = useState<Record<string, Reflection>>({});
  const [expandedId, setExpandedId] = useState<string | null>(values[0].id);

  const handleReflect = (valueId: string, rating: number, notes: string) => {
    setReflections((prev) => ({
      ...prev,
      [valueId]: { rating, notes },
    }));
  };

  return (
    <div className="app">
      <header className="header">
        <h1>African AI Values Explorer</h1>
        <p className="subtitle">
          Reflect on how pluriversal AI values apply to your work
        </p>
      </header>

      <div className="main-content">
        <div className="values-column">
          {values.map((value) => (
            <ValueCard
              key={value.id}
              value={value}
              reflection={reflections[value.id] || { rating: 0, notes: '' }}
              onReflect={(rating, notes) => handleReflect(value.id, rating, notes)}
              isExpanded={expandedId === value.id}
              onToggle={() => setExpandedId(expandedId === value.id ? null : value.id)}
            />
          ))}
        </div>

        <div className="summary-column">
          <Summary reflections={reflections} />
        </div>
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #7c3aed 0%, #a78bfa 100%);
  min-height: 100vh;
  padding: 1.5rem 1rem;
}

.app {
  max-width: 1100px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.95rem;
}

.main-content {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 1.5rem;
}

@media (max-width: 900px) {
  .main-content {
    grid-template-columns: 1fr;
  }
  .summary-column {
    order: -1;
  }
}

.values-column {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.value-card {
  background: white;
  border-radius: 0.75rem;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  transition: box-shadow 0.2s;
}

.value-card.expanded {
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.value-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem;
  border-left: 4px solid;
  cursor: pointer;
  background: #f9fafb;
}

.value-header:hover {
  background: #f3f4f6;
}

.value-title {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 600;
  color: #1f2937;
}

.value-icon {
  font-size: 1.25rem;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.rating-display {
  display: flex;
  gap: 0.15rem;
  font-size: 0.6rem;
  color: #d1d5db;
}

.rating-display .filled {
  color: #6366f1;
}

.expand-icon {
  color: #9ca3af;
  font-size: 1.25rem;
}

.value-content {
  padding: 0 1rem 1rem;
  border-top: 1px solid #e5e7eb;
}

.value-description {
  color: #4b5563;
  font-size: 0.9rem;
  line-height: 1.5;
  margin: 1rem 0;
}

.reflection-questions,
.examples-section {
  background: #f9fafb;
  padding: 0.75rem;
  border-radius: 0.5rem;
  margin-bottom: 0.75rem;
}

.reflection-questions h4,
.examples-section h4 {
  font-size: 0.8rem;
  color: #374151;
  margin-bottom: 0.5rem;
}

.reflection-questions ul,
.examples-section ul {
  list-style: none;
  padding-left: 0;
}

.reflection-questions li,
.examples-section li {
  font-size: 0.85rem;
  color: #4b5563;
  padding-left: 1.25rem;
  position: relative;
  margin-bottom: 0.35rem;
  line-height: 1.4;
}

.reflection-questions li::before {
  content: '?';
  position: absolute;
  left: 0.25rem;
  color: #6366f1;
  font-weight: bold;
}

.examples-section li::before {
  content: '→';
  position: absolute;
  left: 0.25rem;
  color: #9ca3af;
}

.reflection-input {
  margin-top: 1rem;
}

.reflection-input h4 {
  font-size: 0.9rem;
  color: #1f2937;
  margin-bottom: 0.5rem;
}

.reflection-prompt {
  font-size: 0.85rem;
  color: #6b7280;
  margin-bottom: 0.75rem;
}

.rating-input {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

.rating-label {
  font-size: 0.7rem;
  color: #9ca3af;
}

.rating-buttons {
  display: flex;
  gap: 0.35rem;
}

.rating-btn {
  width: 32px;
  height: 32px;
  border: 2px solid #e5e7eb;
  border-radius: 50%;
  background: white;
  font-size: 0.8rem;
  font-weight: 600;
  color: #6b7280;
  cursor: pointer;
  transition: all 0.15s;
}

.rating-btn:hover {
  border-color: #6366f1;
  color: #6366f1;
}

.rating-btn.selected {
  border-color: transparent;
  color: white;
}

.notes-input {
  width: 100%;
  min-height: 80px;
  padding: 0.75rem;
  border: 1px solid #e5e7eb;
  border-radius: 0.5rem;
  font-size: 0.85rem;
  resize: vertical;
  line-height: 1.4;
}

.notes-input:focus {
  outline: none;
  border-color: #6366f1;
}

/* Summary Panel */
.summary-column {
  position: sticky;
  top: 1.5rem;
  height: fit-content;
}

.summary-panel {
  background: white;
  border-radius: 0.75rem;
  padding: 1.25rem;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.summary-panel h2 {
  font-size: 1rem;
  color: #1f2937;
  margin-bottom: 1rem;
}

.progress-section {
  margin-bottom: 1rem;
}

.progress-bar {
  height: 8px;
  background: #e5e7eb;
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 0.25rem;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #6366f1, #a78bfa);
  transition: width 0.3s;
}

.progress-text {
  font-size: 0.75rem;
  color: #6b7280;
}

.avg-rating {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem;
  background: #f9fafb;
  border-radius: 0.5rem;
  margin-bottom: 1rem;
}

.avg-label {
  font-size: 0.85rem;
  color: #4b5563;
}

.avg-value {
  font-size: 1.1rem;
  font-weight: 700;
  color: #6366f1;
}

.strengths-section,
.growth-section {
  margin-bottom: 0.75rem;
}

.strengths-section h4,
.growth-section h4 {
  font-size: 0.8rem;
  color: #374151;
  margin-bottom: 0.5rem;
}

.tag-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}

.tag {
  font-size: 0.7rem;
  padding: 0.25rem 0.5rem;
  border-radius: 0.25rem;
  font-weight: 500;
}

.tag.strength {
  background: #d1fae5;
  color: #047857;
}

.tag.growth {
  background: #fef3c7;
  color: #b45309;
}

.insight-box {
  background: #f5f3ff;
  border: 1px solid #ddd6fe;
  border-radius: 0.5rem;
  padding: 0.75rem;
  margin-top: 1rem;
}

.insight-box h4 {
  font-size: 0.85rem;
  color: #5b21b6;
  margin-bottom: 0.5rem;
}

.insight-box p {
  font-size: 0.8rem;
  color: #6b21a8;
  line-height: 1.4;
  margin-bottom: 0.5rem;
}

.insight-box p:last-child {
  margin-bottom: 0;
}
